(()=>{'use strict';const host=document.querySelector('#cap-chart');if(!host)return;const detail={name:document.querySelector('#cap-detail-name'),region:document.querySelector('#cap-detail-region'),aum:document.querySelector('#cap-detail-aum'),q:document.querySelector('#cap-detail-q1q5')};const body=document.querySelector('#cap-table-body');let rows=[];const pct=(n)=>new Intl.NumberFormat('it-IT',{style:'percent',maximumFractionDigits:1}).format(n);const rank=(n)=>(n*100).toFixed(1).replace('.',',')+'°';function choose(x){document.querySelectorAll('.cap-bar-row').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.name===x.name)));document.querySelectorAll('.cap-table tbody tr').forEach(r=>r.classList.toggle('is-active',r.dataset.name===x.name));detail.name.textContent=x.name;detail.region.textContent=x.region+' · '+x.group.toLowerCase();detail.aum.textContent=rank(x.aum);detail.q.textContent=pct(x.q1q5)}fetch('/data/4-2-province-extremes.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{rows=d.values;for(const group of ['Tra le più alte','Tra le più basse']){const g=document.createElement('section');g.className='cap-group';g.innerHTML='<h4>'+group.toUpperCase()+'</h4>';rows.filter(x=>x.group===group).forEach(x=>{const b=document.createElement('button');b.type='button';b.className='cap-bar-row';b.dataset.name=x.name;b.dataset.group=group==='Tra le più alte'?'high':'low';b.setAttribute('aria-pressed','false');b.setAttribute('aria-label',x.name+', rango medio '+rank(x.aum)+', passaggio dal quinto più basso al più alto '+pct(x.q1q5));b.innerHTML='<span class="cap-bar-label"></span><span class="cap-bar-rail"><i class="cap-bar"></i></span><b></b>';b.querySelector('.cap-bar-label').textContent=x.name;b.querySelector('.cap-bar').style.setProperty('--width',((x.aum-.34)/(.58-.34)*100).toFixed(1)+'%');b.querySelector('b').textContent=rank(x.aum);b.addEventListener('click',()=>choose(x));g.append(b)});host.append(g)}rows.forEach(x=>{const tr=document.createElement('tr');tr.dataset.name=x.name;tr.tabIndex=0;tr.innerHTML='<td></td><td></td><td></td><td></td>';tr.children[0].textContent=x.name;tr.children[1].textContent=x.group;tr.children[2].textContent=rank(x.aum);tr.children[3].textContent=pct(x.q1q5);tr.addEventListener('click',()=>choose(x));tr.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(x)}});body.append(tr)});choose(rows[0]);document.querySelector('#cap-download').addEventListener('click',()=>{const csv='Provincia,Regione,Selezione pubblicata,Rango medio figli,Q1Q5\n'+rows.map(x=>[x.name,x.region,x.group,(x.aum*100).toFixed(1),pct(x.q1q5)].join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download='4-2-province-pubblicate.csv';a.click();URL.revokeObjectURL(a.href)})}).catch(()=>{host.innerHTML='<p class="data-error">I dati non sono disponibili. Consulta le tabelle 15 e 16 dello studio dalla sezione fonti.</p>'})})();